verus! {
    /// Given `n >= 0` and `k >= 1`, returns the minimal non‐negative distance
    /// from `n` to a multiple of `k`.  Formally, if `r = n % k`, returns
    /// `min(r, k-r)`.
    fn solve(n: i8, k: i8) -> (result: i8)
        requires n >= 0
        requires k >= 1
        ensures 0 <= result
        ensures result < k
        ensures 
            // stepping up or down by result reaches a multiple of k
            (n + result) % k == 0 ||
            (n - result) % k == 0
        ensures
            // result is no larger than going downward by r = n%k
            result <= n % k
        ensures
            // result is no larger than going upward by k - r
            result <= (k - (n % k))
    {
        // Compute the standard nonnegative remainder 0 <= r < k
        let r: i8 = n % k;
        assert(r >= 0);
        assert(r < k);

        if r <= k - r {
            // it's closer (or equally close) to step down by r
            result = r;
        } else {
            // otherwise it's closer to step up by k - r
            result = k - r;
        }
    }
}

